import math

def euclidean_distance(a, b):
    # already covered generally as a distance metric in Metric Learning
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def average_vector(vectors):
    # already covered as prototypical networks introduced in this topic
    dims = len(vectors[0])
    return [sum(v[d] for v in vectors) / len(vectors) for d in range(dims)]

# already covered as the n support example format in this topic
support_examples = {
    "cat": [[0.9, 0.1], [0.85, 0.15], [0.92, 0.08]],
    "dog": [[0.2, 0.9], [0.25, 0.85], [0.18, 0.92]],
}

# already covered as prototypical networks introduced in this topic
prototypes = {label: average_vector(examples) for label, examples in support_examples.items()}
print(f"Class prototypes, averaged from support examples (already covered in this topic): {prototypes}")

new_example = [0.88, 0.12]  # already covered as a new example to classify in this topic
print(f"\nClassifying new example {new_example} (already covered in this topic):")
distances = {label: euclidean_distance(new_example, proto) for label, proto in prototypes.items()}
for label, dist in distances.items():
    print(f"  distance to '{label}' prototype: {dist:.3f}")

predicted_label = min(distances, key=distances.get)
print(f"\nPredicted class: '{predicted_label}'")
